@namespace sv_0272fb52e465477c9457ff332e4988b6.Components.JobApplication
@using sv_0272fb52e465477c9457ff332e4988b6.Services

<div class="step-content">
    <h4 class="mb-3">Review & Submit</h4>

    @if (IsSubmitted)
    {
        <div class="alert alert-success">
            <h5>Application Submitted Successfully!</h5>
