<div class="step-content">
    <h4 class="mb-3">Personal Information</h4>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger">@ErrorMessage</div>
    }

    <div class="row g-3">
        <div class="col-md-6">
            <label class="form-label">Full Name *</label>
            <input type="text" class="form-control" value="@FullName"
                   @onchange="e => FullName = e.Value?.ToString() ?? "" " />
        </div>
        <div class="col-md-6">
            <label class="form-label">Email *</label>
            <input type="email" class="form-control @(emailInvalid ? "is-invalid" : "")" value="@Email"
                   @onchange="e => { Email = e.Value?.ToString() ?? ""; emailInvalid = false; }" />
            @if (emailInvalid)
            {
                <div class="invalid-feedback">Please enter a valid email address.</div>
            }
        </div>
        <div class="col-md-6">
            <label class="form-label">Phone *</label>
            <input type="tel" class="form-control" value="@Phone"
                   @onchange="e => Phone = e.Value?.ToString() ?? "" " />
        </div>
        <div class="col-md-6">
            <label class="form-label">Address *</label>
            <input type="text" class="form-control" value="@Address"
                   @onchange="e => Address = e.Value?.ToString() ?? "" " />
        </div>
    </div>

    <div class="mt-4 d-flex justify-content-end">
        <button class="btn btn-primary" @onclick="HandleNext" disabled="@isValidating">
            @if (isValidating)
            {
                <span class="spinner-border spinner-border-sm me-1"></span>
            }
            Next
        </button>
    </div>
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<PersonalInfoData> OnNext { get; set; }
    [Parameter, EditorRequired] public Func<string, Task<bool>> ValidateEmail { get; set; } = default!;

    private string ErrorMessage = "";
    private bool emailInvalid;
    private bool isValidating;

    private async Task HandleNext()
    {
        ErrorMessage = "";
        emailInvalid = false;

        if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email)
            || string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
        {
            ErrorMessage = "All fields are required.";
            return;
        }

        isValidating = true;
        try
        {
            var valid = await ValidateEmail(Email);
            if (!valid)
            {
                emailInvalid = true;
                return;
            }
        }
        finally
        {
            isValidating = false;
        }

        await OnNext.InvokeAsync(new PersonalInfoData(FullName, Email, Phone, Address));
    }

    public record PersonalInfoData(string FullName, string Email, string Phone, string Address);
}

