@namespace sv_0272fb52e465477c9457ff332e4988b6.Components.JobApplication

<nav class="step-indicator">
    @for (int i = 0; i < StepNames.Count; i++)
    {
        var stepIndex = i;
        var css = GetStepCss(stepIndex);
        <div class="step @css" @onclick="() => OnStepClick(stepIndex)">
            <div class="step-circle">
                @if (CompletedSteps.Contains(stepIndex))
                {
                    <span>&#10003;</span>
                }
                else
                {
                    <span>@(stepIndex + 1)</span>
                }
            </div>
            <div class="step-label">@StepNames[stepIndex]</div>
        </div>
        @if (stepIndex < StepNames.Count - 1)
        {
            <div class="step-connector @(CompletedSteps.Contains(stepIndex) ? "completed" : "")"></div>
        }
    }
</nav>

<style>
    .step-indicator {
        display: flex;
        align-items: center;
        justify-content: center;
        margin-bottom: 2rem;
        padding: 1rem 0;
    }
    .step {
        display: flex;
        flex-direction: column;
        align-items: center;
        cursor: default;
        opacity: 0.4;
        transition: opacity 0.2s;
    }
    .step.active {
        opacity: 1;
    }
    .step.completed {
        opacity: 0.8;
        cursor: pointer;
    }
    .step-circle {
        width: 36px;
        height: 36px;
        border-radius: 50%;
        background: #dee2e6;
        display: flex;
        align-items: center;
        justify-content: center;
        font-weight: bold;
        font-size: 0.9rem;
        margin-bottom: 0.4rem;
    }
    .step.active .step-circle {
        background: #0d6efd;
        color: white;
    }
    .step.completed .step-circle {
        background: #198754;
        color: white;
    }
    .step-label {
        font-size: 0.75rem;
        text-align: center;
        max-width: 80px;
    }
    .step-connector {
        flex: 1;
        height: 2px;
        background: #dee2e6;
        margin: 0 0.5rem;
        margin-bottom: 1.5rem;
    }
    .step-connector.completed {
        background: #198754;
    }
</style>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter, EditorRequired] public List<string> StepNames { get; set; } = new();
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }

    private string GetStepCss(int index)
    {
        if (index == CurrentStep) return "active";
        if (CompletedSteps.Contains(index)) return "completed";
        return "";
    }

    private async Task OnStepClick(int index)
    {
        if (CompletedSteps.Contains(index))
        {
            await OnStepClicked.InvokeAsync(index);
        }
    }
}

