@page "/apply"
@using sv_0272fb52e465477c9457ff332e4988b6.Components.JobApplication
@using sv_0272fb52e465477c9457ff332e4988b6.Services
@inject IApplicationService ApplicationService
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="text-center mb-4">Job Application</h2>

    <StepIndicator CurrentStep="currentStep"
                   CompletedSteps="completedSteps"
                   StepNames="stepNames"
                   OnStepClicked="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep FullName="@personalFullName"
                              Email="@personalEmail"
                              Phone="@personalPhone"
                              Address="@personalAddress"
                              ValidateEmail="ApplicationService.ValidateEmailAsync"
                              OnNext="HandlePersonalNext" />
            break;

        case 1:
            <WorkHistoryStep Entries="workEntries"
                             OnNext="HandleWorkNext"
                             OnBack="GoBack" />
            break;

        case 2:
            <ReferencesStep References="references"
                            OnNext="HandleReferencesNext"
                            OnBack="GoBack" />
            break;

        case 3:
            <CoverLetterStep CoverLetter="@coverLetter"
                             OnNext="HandleCoverLetterNext"
                             OnBack="GoBack" />
            break;

        case 4:
            <ReviewStep Personal="@GetPersonalInfo()"
                        WorkEntries="@GetWorkEntries()"
                        References="@GetReferences()"
                        CoverLetter="@coverLetter"
                        IsSubmitting="isSubmitting"
                        IsSubmitted="isSubmitted"
                        ApplicationId="applicationId"
                        ErrorMessage="@submitError"
                        OnEditStep="GoToStep"
                        OnBack="GoBack"
                        OnSubmit="HandleSubmit" />
            break;
    }
</div>

@code {
    private int currentStep = 0;
    private HashSet<int> completedSteps = new();
    private List<string> stepNames = new() { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    // Step 1 state
    private string personalFullName = "";
    private string personalEmail = "";
    private string personalPhone = "";
    private string personalAddress = "";

    // Step 2 state
    private List<WorkHistoryStep.EntryModel> workEntries = new() { new() };

    // Step 3 state
    private List<ReferencesStep.ReferenceModel> references = new() { new(), new() };

    // Step 4 state
    private string coverLetter = "";

    // Submission state
    private bool isSubmitting;
    private bool isSubmitted;
    private int applicationId;
    private string submitError = "";

    private void GoToStep(int step)
    {
        currentStep = step;
    }

    private void GoBack()
    {
        if (currentStep > 0)
            currentStep--;
    }

    private void HandlePersonalNext(PersonalInfoStep.PersonalInfoData data)
    {
        personalFullName = data.FullName;
        personalEmail = data.Email;
        personalPhone = data.Phone;
        personalAddress = data.Address;
        completedSteps.Add(0);
        currentStep = 1;
    }

    private void HandleWorkNext(List<WorkHistoryStep.EntryModel> entries)
    {
        workEntries = entries;
        completedSteps.Add(1);
        currentStep = 2;
    }

    private void HandleReferencesNext(List<ReferencesStep.ReferenceModel> refs)
    {
        references = refs;
        completedSteps.Add(2);
        currentStep = 3;
    }

    private void HandleCoverLetterNext(string text)
    {
        coverLetter = text;
        completedSteps.Add(3);
        currentStep = 4;
    }

    private async Task HandleSubmit()
    {
        isSubmitting = true;
        submitError = "";

        try
        {
            var application = new JobApplication(
                GetPersonalInfo(),
                new WorkHistory(GetWorkEntries()),
                GetReferences(),
                coverLetter
            );

            applicationId = await ApplicationService.SubmitApplicationAsync(application);
            isSubmitted = true;
            completedSteps.Add(4);
        }
        catch (Exception ex)
        {
            submitError = $"Submission failed: {ex.Message}. Please try again.";
        }
        finally
        {
            isSubmitting = false;
        }
    }

    private PersonalInfo GetPersonalInfo() =>
        new(personalFullName, personalEmail, personalPhone, personalAddress);

    private List<WorkEntry> GetWorkEntries() =>
        workEntries.Select(e => new WorkEntry(e.Company, e.Title, e.StartDate, e.EndDate, e.Description)).ToList();

    private List<Reference> GetReferences() =>
        references
            .Where(r => !string.IsNullOrWhiteSpace(r.Name))
            .Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone))
            .ToList();
}

